<?php
require_once __DIR__ . '/includes/auth.php';
requireLogin();
$pdo = db(); $uid = userId(); $pageTitle = 'Dashboard'; $activePage = 'dashboard.php';
[$monthStart, $monthEnd] = monthBounds();
$totalIncome = transactionSum($pdo, $uid, 'income');
$totalExpense = transactionSum($pdo, $uid, 'expense');
$incomeMonth = transactionSum($pdo, $uid, 'income', $monthStart, $monthEnd);
$expenseMonth = transactionSum($pdo, $uid, 'expense', $monthStart, $monthEnd);
$balance = $totalIncome - $totalExpense;
$monthBalance = $incomeMonth - $expenseMonth;
$savingsTotal = (float) $pdo->query("SELECT COALESCE(SUM(current_amount),0) FROM savings WHERE user_id = {$uid}")->fetchColumn();
$debtTotal = (float) $pdo->query("SELECT COALESCE(SUM(GREATEST(total_amount-paid_amount,0)),0) FROM debts WHERE user_id = {$uid}")->fetchColumn();
$receivableTotal = (float) $pdo->query("SELECT COALESCE(SUM(GREATEST(total_amount-paid_amount,0)),0) FROM receivables WHERE user_id = {$uid}")->fetchColumn();
$netWorth = $balance + $savingsTotal + $receivableTotal - $debtTotal;
$recentStmt = $pdo->prepare('SELECT * FROM transactions WHERE user_id = ? ORDER BY transaction_date DESC, id DESC LIMIT 7'); $recentStmt->execute([$uid]); $recent = $recentStmt->fetchAll();
$goalStmt = $pdo->prepare('SELECT * FROM financial_goals WHERE user_id = ? AND status = "Aktif" ORDER BY deadline IS NULL, deadline LIMIT 3'); $goalStmt->execute([$uid]); $goals = $goalStmt->fetchAll();
$budgetStmt = $pdo->prepare('SELECT b.*, COALESCE((SELECT SUM(t.amount) FROM transactions t WHERE t.user_id=b.user_id AND t.type="expense" AND t.category=b.category AND t.transaction_date BETWEEN CONCAT(b.year,"-",LPAD(b.month,2,"0"),"-01") AND LAST_DAY(CONCAT(b.year,"-",LPAD(b.month,2,"0"),"-01"))),0) used_amount FROM budgets b WHERE b.user_id=? AND b.month=? AND b.year=? ORDER BY used_amount DESC'); $budgetStmt->execute([$uid,(int)date('m'),(int)date('Y')]); $budgets = $budgetStmt->fetchAll();
$monthlyLabels=[];$monthlyIncome=[];$monthlyExpense=[];$monthlyBalance=[];$running=0;
for($i=5;$i>=0;$i--){$stamp=strtotime("first day of -{$i} month");$label=date('M Y',$stamp);$start=date('Y-m-01',$stamp);$end=date('Y-m-t',$stamp);$monthlyLabels[]=$label;$monthlyIncome[]=transactionSum($pdo,$uid,'income',$start,$end);$monthlyExpense[]=transactionSum($pdo,$uid,'expense',$start,$end);$running += $monthlyIncome[array_key_last($monthlyIncome)]-$monthlyExpense[array_key_last($monthlyExpense)];$monthlyBalance[]=$running;}
$catStmt=$pdo->prepare('SELECT category,SUM(amount) total FROM transactions WHERE user_id=? AND type="expense" AND transaction_date BETWEEN ? AND ? GROUP BY category ORDER BY total DESC LIMIT 7');$catStmt->execute([$uid,$monthStart,$monthEnd]);$catRows=$catStmt->fetchAll();$catLabels=array_column($catRows,'category');$catValues=array_map('floatval',array_column($catRows,'total'));
$insights=[];
if($catRows){$insights[]='Pengeluaran terbesar bulan ini berasal dari kategori <strong>'.e($catRows[0]['category']).'</strong> sebesar '.formatRupiah($catRows[0]['total']).'.';}
[$prevStart,$prevEnd]=monthBounds(date('Y-m',strtotime('-1 month')));$prevExpense=transactionSum($pdo,$uid,'expense',$prevStart,$prevEnd);if($prevExpense>0 && $expenseMonth>$prevExpense){$insights[]='Pengeluaran bulan ini naik '.number_format((($expenseMonth-$prevExpense)/$prevExpense)*100,1,',','.').'% dibanding bulan lalu.';}elseif($prevExpense>0){$insights[]='Pengeluaran bulan ini lebih rendah dibandingkan bulan lalu. Pertahankan ritmenya.';}
foreach($budgets as $budget){$used=(float)$budget['used_amount'];$percent=percentage($used,(float)$budget['amount']);if($percent>=85){$insights[]='Budget kategori <strong>'.e($budget['category']).'</strong> sudah mencapai '.number_format($percent,1,',','.').'%. ';break;}}
foreach($goals as $goal){$percent=percentage((float)$goal['current_amount'],(float)$goal['target_amount']);if($percent>=50){$insights[]='Target <strong>'.e($goal['name']).'</strong> sudah mencapai '.number_format($percent,1,',','.').'%. ';break;}}
$soonStmt=$pdo->prepare('SELECT name,due_date FROM bills WHERE user_id=? AND status="Belum Dibayar" AND due_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 3 DAY) LIMIT 1');$soonStmt->execute([$uid]);if($soon=$soonStmt->fetch())$insights[]='Tagihan <strong>'.e($soon['name']).'</strong> jatuh tempo dalam 3 hari.';
if($receivableTotal>0)$insights[]='Masih ada piutang sebesar <strong>'.formatRupiah($receivableTotal).'</strong> yang belum diterima.';
if(!$insights)$insights[]='Belum ada insight khusus. Tambahkan transaksi agar kondisi keuanganmu semakin terbaca.';
$user=currentUser($pdo); require __DIR__.'/includes/header.php';
?>
