<div class="stats-grid"><div class="stat-card card kpi-highlight"><div class="stat-top"><span>Saldo Saat Ini</span><span class="stat-icon"><i data-lucide="wallet"></i></span></div><div class="stat-value"><?= formatRupiah($balance) ?></div><div class="stat-meta">Pemasukan total dikurangi pengeluaran</div></div><div class="stat-card card"><div class="stat-top"><span>Pemasukan Bulan Ini</span><span class="stat-icon"><i data-lucide="trending-up"></i></span></div><div class="stat-value positive"><?= formatRupiah($incomeMonth) ?></div><div class="stat-meta"><?= e(date('F Y')) ?></div></div><div class="stat-card card"><div class="stat-top"><span>Pengeluaran Bulan Ini</span><span class="stat-icon"><i data-lucide="trending-down"></i></span></div><div class="stat-value negative"><?= formatRupiah($expenseMonth) ?></div><div class="stat-meta"><?= e(date('F Y')) ?></div></div><div class="stat-card card"><div class="stat-top"><span>Sisa Uang Bulan Ini</span><span class="stat-icon"><i data-lucide="sparkles"></i></span></div><div class="stat-value <?= $monthBalance>=0?'positive':'negative' ?>"><?= formatRupiah($monthBalance) ?></div><div class="stat-meta">Arus kas bulan berjalan</div></div></div>
<div class="stats-grid"><div class="stat-card card"><div class="stat-top"><span>Total Tabungan</span><span class="stat-icon"><i data-lucide="piggy-bank"></i></span></div><div class="stat-value"><?= formatRupiah($savingsTotal) ?></div><div class="stat-meta">Alokasi target uang</div></div><div class="stat-card card"><div class="stat-top"><span>Total Utang</span><span class="stat-icon"><i data-lucide="credit-card"></i></span></div><div class="stat-value negative"><?= formatRupiah($debtTotal) ?></div><div class="stat-meta">Sisa yang belum lunas</div></div><div class="stat-card card"><div class="stat-top"><span>Total Piutang</span><span class="stat-icon"><i data-lucide="hand-coins"></i></span></div><div class="stat-value positive"><?= formatRupiah($receivableTotal) ?></div><div class="stat-meta">Sisa yang harus diterima</div></div><div class="stat-card card"><div class="stat-top"><span>Net Worth</span><span class="stat-icon"><i data-lucide="badge-dollar-sign"></i></span></div><div class="stat-value"><?= formatRupiah($netWorth) ?></div><div class="stat-meta">Saldo + tabungan + piutang - utang</div></div></div>
<div class="grid-main"><section class="card"><div class="card-header"><div><h2 class="card-title">Pemasukan vs Pengeluaran</h2><p class="card-subtitle">Tren enam bulan terakhir</p></div><a class="btn btn-soft btn-sm" href="laporan.php">Lihat laporan</a></div><div class="chart-wrap"><canvas id="cashflowChart"></canvas></div></section><section class="card"><div class="card-header"><div><h2 class="card-title">Pengeluaran per Kategori</h2><p class="card-subtitle">Bulan berjalan</p></div></div><div class="chart-wrap small"><canvas id="categoryChart"></canvas></div></section></div>
<div class="grid-two"><section class="card"><div class="card-header"><div><h2 class="card-title">Perkembangan Saldo</h2><p class="card-subtitle">Akumulasi arus kas enam bulan terakhir</p></div></div><div class="chart-wrap small"><canvas id="balanceChart"></canvas></div></section><section class="card"><div class="card-header"><div><h2 class="card-title">Aksi Cepat</h2><p class="card-subtitle">Satu klik untuk menjaga catatan tetap rapi</p></div></div><div class="quick-actions"><a class="quick-action" href="pemasukan.php?action=add"><i><i data-lucide="arrow-down-left"></i></i>Tambah Pemasukan</a><a class="quick-action" href="pengeluaran.php?action=add"><i><i data-lucide="arrow-up-right"></i></i>Tambah Pengeluaran</a><a class="quick-action" href="tabungan.php?action=add"><i><i data-lucide="piggy-bank"></i></i>Tambah Tabungan</a><a class="quick-action" href="utang.php?action=add"><i><i data-lucide="credit-card"></i></i>Tambah Utang</a><a class="quick-action" href="piutang.php?action=add"><i><i data-lucide="hand-coins"></i></i>Tambah Piutang</a><a class="quick-action" href="tagihan.php?action=add"><i><i data-lucide="receipt-text"></i></i>Tambah Tagihan</a></div></section></div>
<div class="grid-two"><section class="card"><div class="card-header"><div><h2 class="card-title">Transaksi Terbaru</h2><p class="card-subtitle">Aktivitas keuangan terakhir</p></div><a class="btn btn-ghost btn-sm" href="pencarian.php">Lihat semua</a></div><?php if(!$recent): ?><div class="empty-state"><div class="empty-icon"><i data-lucide="inbox"></i></div><strong>Belum ada transaksi.</strong><p>Mulai catat pemasukan atau pengeluaran pertamamu.</p><a class="btn btn-primary btn-sm" href="pemasukan.php?action=add">Tambah Transaksi</a></div><?php else: ?><div class="list"><?php foreach($recent as $item): ?><div class="transaction-row"><div class="type-dot <?= e($item['type']) ?>"><i data-lucide="<?= $item['type']==='income'?'arrow-down-left':'arrow-up-right' ?>"></i></div><div class="row-main"><strong><?= e($item['description'] ?: $item['category']) ?></strong><small><?= e($item['category']) ?> · <?= e(date('d/m/Y',strtotime($item['transaction_date']))) ?></small></div><div class="row-amount <?= e($item['type']) ?>"><?= $item['type']==='income'?'+':'-' ?><?= formatRupiah($item['amount']) ?></div></div><?php endforeach; ?></div><?php endif; ?></section><section class="card"><div class="card-header"><div><h2 class="card-title">Insight Keuangan</h2><p class="card-subtitle">Sinyal sederhana dari datamu</p></div><span class="stat-icon"><i data-lucide="lightbulb"></i></span></div><div class="insight-list"><?php foreach($insights as $insight): ?><div class="insight"><div class="insight-icon"><i data-lucide="sparkles"></i></div><span><?= $insight ?></span></div><?php endforeach; ?></div></section></div>
<?php if($budgets): ?><section class="card" style="margin-bottom:18px"><div class="card-header"><div><h2 class="card-title">Progress Budget Bulan Ini</h2><p class="card-subtitle">Tetap dekat dengan rencana pengeluaranmu</p></div><a class="btn btn-ghost btn-sm" href="budget.php">Kelola budget</a></div><div class="grid-two" style="margin:0"><?php foreach($budgets as $budget): [$label,$tone,$percent]=statusBudget((float)$budget['used_amount'],(float)$budget['amount']); ?><div><div class="progress-meta"><span><strong><?= e($budget['category']) ?></strong> · <?= e($label) ?></span><span><?= number_format($percent,1,',','.') ?>%</span></div><div class="progress-line"><div class="progress-fill <?= e($tone) ?>" style="width:<?= $percent ?>%"></div></div><div class="form-hint" style="margin-top:5px"><?= formatRupiah($budget['used_amount']) ?> dari <?= formatRupiah($budget['amount']) ?></div></div><?php endforeach; ?></div></section><?php endif; ?>
<?php $chartData=['labels'=>$monthlyLabels,'income'=>$monthlyIncome,'expense'=>$monthlyExpense,'balance'=>$monthlyBalance,'categoryLabels'=>$catLabels,'categoryValues'=>$catValues];$pageScripts='<script>const dashboardData='.json_encode($chartData,JSON_UNESCAPED_UNICODE).';const gridColor="rgba(123,135,158,.15)";const base={responsive:true,maintainAspectRatio:false,plugins:{legend:{labels:{font:{family:"Inter",size:11},usePointStyle:true,boxWidth:8}}},scales:{x:{grid:{display:false},ticks:{color:"#9aa5b8",font:{size:10}}},y:{grid:{color:gridColor},ticks:{color:"#9aa5b8",font:{size:10},callback:v=>"Rp "+new Intl.NumberFormat("id-ID",{notation:"compact"}).format(v)}}}};new Chart(document.getElementById("cashflowChart"),{type:"bar",data:{labels:dashboardData.labels,datasets:[{label:"Pemasukan",data:dashboardData.income,backgroundColor:"#18a999",borderRadius:8},{label:"Pengeluaran",data:dashboardData.expense,backgroundColor:"#ec8b75",borderRadius:8}]},options:base});new Chart(document.getElementById("categoryChart"),{type:"doughnut",data:{labels:dashboardData.categoryLabels.length?dashboardData.categoryLabels:["Belum ada data"],datasets:[{data:dashboardData.categoryValues.length?dashboardData.categoryValues:[1],backgroundColor:["#5b62da","#18a999","#ec8b75","#e9aa43","#8e73dc","#4b9ec7","#a8b1c3"],borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:"bottom",labels:{font:{family:"Inter",size:10},usePointStyle:true,boxWidth:8}}}}});new Chart(document.getElementById("balanceChart"),{type:"line",data:{labels:dashboardData.labels,datasets:[{label:"Saldo",data:dashboardData.balance,borderColor:"#5b62da",backgroundColor:"rgba(91,98,218,.12)",fill:true,tension:.38,pointRadius:3}]},options:base});</script>';require __DIR__.'/includes/footer.php';